const norm = (s) => s.trim().replace(/\s+/g, " ").toLowerCase();
const MAPS = {};
function mapFor(lang) {
  if (MAPS[lang]) return MAPS[lang];
  const arr = T[lang];
  if (!arr) return null;
  const m = new Map();
  KEYS.forEach((k, i) => { if (!m.has(norm(k))) m.set(norm(k), arr[i]); });
  return (MAPS[lang] = m);
}

/** Languages that work fully offline. */
export const OFFLINE_LANGUAGES = Object.keys(T);
export const hasOffline = (lang) => !!T[lang];

/** Translate one UI string offline, or return null. Handles "Good morning, Name" and "A · B" style labels. */
export function translateOffline(lang, text) {
  const m = mapFor(lang);
  if (!m || !text) return null;
  const hit = m.get(norm(text));
  if (hit) return hit;
  const parts = text.split(/(\s·\s|,\s|\s—\s|:\s)/);
  if (parts.length < 3) return null;
  let changed = false;
  const outp = parts.map((p, i) => {
    if (i % 2) return p;
    const h = p.trim() && m.get(norm(p));
    if (h) { changed = true; return p.replace(p.trim(), h); }
    return p;
  });
  return changed ? outp.join("") : null;
}

export const isRtl = (lang) => lang === "Arabic" || lang === "Urdu";
